contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        uint balBeforeC = address(c).balance;
        // forward() passes no value and empty data, so the callee's payable
        // receive() succeeds; forward must therefore not revert, and since it
        // never attaches value nor lets the callee push Ether (empty data,
        // zero value), c's balance is unchanged.
        bytes memory data = "";
        bool reverted;
        c.forward(address(this), data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted && address(c).balance == balBeforeC);
    }
    receive() external payable {}
}

